if ~exist('src200s','var')
    src200s = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei200_align_sym3.sqw');
end
file = src200s.full_filename %[output:5d335bdf]
[~,fname] = fileparts(file);
w2_00 = cut(src200s,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]); %[output:785db43f]
plot(w2_00);liny; lz 0 1; keep_figure; %[output:87555db2]

hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;
%%
Add_binsHN200 = {[-0.1,0.1],[-0.1,0.1],[0,4,200]};

%w2_200a1 = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]),[0.04],Add_bins{:});
%plot(w2_200a1);liny; lz 0 1;keep_figure;
%w2_200a2 = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[1.5,0.5,0]),[0.04],Add_bins{:});
%plot(w2_200a2); lz 0 1;keep_figure;

w2_200a = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]),0.02,Add_binsHN200{:},SymopReflection('norm',[-1,1,0],'offset',[1,1,0]));
plot(w2_200a);liny; lz 0 0.3;keep_figure; %[output:7a8816fe]


w2_200b = cut(src200s,line_proj([-1,1,0],[1,1,0],'offset',[2,1,0]),0.02,Add_binsHN200{:});
plot(w2_200b); lz 0 0.3;keep_figure; %[output:16225147]


% w2_200c = cut(src200s,line_proj([1,1,0],[-1,1,0],'offset',[1,1,1]),[0.04],Add_bins{:},SymopReflection('norm',[-1,1,0],'offset',[1,1,0]));
% plot(w2_200c);liny; lz 0 0.3;keep_figure;

%%
bg_200b2 = cut(src200s,line_proj([-1,1,0],[1,1,0],'offset',[3,2,0]),0.04,Add_binsHN200{:});
plot(bg_200b2);liny; lz 0 0.1;keep_figure; %[output:760fc1ad]

bg1 = cut(src200s,line_proj([-1,1,0],[1,1,0],'offset',[3,2,0]),[-1,2],Add_binsHN200{:});
plot(bg1);logy; keep_figure; %[output:1a4ed263]

%%
w2nbg = repmat(sqw,1,2);
w2nbg(1) = w2_200a - replicate(bg1,w2_200a);
w2nbg(1) = cut(w2nbg(1),[-0.5,0.02,1.5],[0,4,200]);
plot(w2nbg(1));liny; lz 0 0.1;keep_figure; %[output:91d9a980]

w2nbg(2) = w2_200b - replicate(bg1,w2_200b);
w2nbg(2) = cut(w2nbg(2),[-1,0.02,2],[0,4,200]);
plot(w2nbg(2));liny; lz 0 0.1;keep_figure; %[output:39f76144]
%%

%%
if ~exist('mion','var')
    mion = MagneticIons();
end
w2nbgc = repmat(sqw,1,2);
for i=1:2 %[output:group:69a97975]
    w2nbgc(i) = mion.correct_mag_ff(w2nbg(i));
    plot(w2nbgc(i)); lz 0 1;keep_figure;drawnow %[output:0b040849] %[output:5d2f5770]
end %[output:group:69a97975]
%%
 w2s1 = symmetrise_sqw(w2nbgc(2),{SymopReflection('norm',[-1,1,0],'offset',[2,1,0]),SymopReflection('norm',[1,-1,0],'offset',[1,2,0])});
 plot(w2s1); lz 0 1;keep_figure; %[output:7fd19632]
%%
w2s2 = symmetrise_sqw(w2s1,SymopReflection('norm',[1,-1,0],'offset',[1.5,1.5,0]));

w2s2.full_filename = [fname,' HN Ei200, one cut sum, bg removed, ff corrected'];
plot(w2s2); lz 0 1;keep_figure; %[output:815dbede]
%%
ff = gcf %[output:94e04a0d]
savefig(ff,'sHN_Ei200_2Sym_bg_rem_ff_corr');


